import{r as t}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as n,o,c as a,b6 as i,J as u,k as l}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse(`{"title":"De l'idée au produit AI - Parcours d'apprentissage Easy-Vibe","description":"Parcours d'apprentissage complet de la programmation AI : de zéro au développement full-stack. Maîtrisez le Vibe Coding, Claude Code, Cursor et d'autres outils IDE AI, apprenez la réflexion produit, le développement full-stack et l'intégration de capacités AI.","frontmatter":{"title":"De l'idée au produit AI - Parcours d'apprentissage Easy-Vibe","description":"Parcours d'apprentissage complet de la programmation AI : de zéro au développement full-stack. Maîtrisez le Vibe Coding, Claude Code, Cursor et d'autres outils IDE AI, apprenez la réflexion produit, le développement full-stack et l'intégration de capacités AI."},"headers":[],"relativePath":"fr-fr/stage-1/learning-map/index.md","filePath":"fr-fr/stage-1/learning-map/index.md"}`),p={name:"fr-fr/stage-1/learning-map/index.md"},h=Object.assign(p,{setup(d){const r=t["fr-fr/stage-1/learning-map"]??[];return(c,e)=>{const s=n("RelatedArticlesSection");return o(),a("div",null,[e[0]||(e[0]=i('<h1 id="de-l-idee-au-produit-ai" tabindex="-1">De l&#39;idée au produit AI <a class="header-anchor" href="#de-l-idee-au-produit-ai" aria-label="Permalink to “De l&#39;idée au produit AI”">​</a></h1><div class="info custom-block"><p class="custom-block-title">Remerciements spéciaux</p><p>Un grand merci aux étudiants de l&#39;<strong>Université Tsinghua, Campus international de Shenzhen</strong> pour leurs tests, retours et soutien de ce cours ! Vos avis et contributions ont permis d&#39;améliorer ce cours. <a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 Voir la liste complète des contributeurs</a></p></div><p>Autrefois, créer un logiciel était un processus très exigeant : il fallait connaître la programmation, comprendre les algorithmes et avoir des années d&#39;expérience en projet. Aujourd&#39;hui, tout a changé. Si vous avez une idée, l&#39;IA peut écrire le code pour vous.</p><p>C&#39;est un changement majeur : <strong>les langages de programmation deviennent des langages naturels</strong>.</p><p>L&#39;apparition des grands modèles de langage (LLM) a fait en sorte que le développement n&#39;est plus « l&#39;apanage des experts techniques », mais un outil que tout le monde peut prendre en main. Ce qui était autrefois le plus difficile — « comment écrire du code » — est devenu ce qui est le plus difficile aujourd&#39;hui : « <strong>que voulez-vous créer</strong> ».</p><blockquote><p><strong>Qu&#39;est-ce que le Vibe Coding ?</strong> En termes simples, c&#39;est « programmer en parlant ». Le Vibe Coding signifie que vous pouvez réaliser un projet de programmation en vous appuyant uniquement sur des conversations avec l&#39;IA, plutôt que d&#39;écrire du code directement.</p></blockquote><p>Bien sûr, faire en sorte que l&#39;IA écrive du code n&#39;est que la première étape. Pour créer un produit véritablement utilisable, vous rencontrerez d&#39;autres défis :</p><ul><li>Comment faire en sorte que l&#39;IA écrive un code propre et maintenable ?</li><li>Comment assembler des fragments de code en une application fonctionnelle ?</li><li>Comment mettre une application en ligne et la faire utiliser par de vrais utilisateurs ?</li><li>Comment intégrer des capacités AI comme la génération de texte et la reconnaissance d&#39;images dans votre produit ?</li></ul><p>Ce cours vous aidera à trouver des réponses à ces questions.</p><p>Que vous soyez étudiant, enseignant, médecin, ouvrier, ou toute personne sans aucune connaissance technique — sans avoir besoin d&#39;apprendre la programmation pendant des années, vous pourrez en deux semaines créer un prototype fonctionnel et démontrable.</p><table tabindex="0"><thead><tr><th>Votre profil</th><th>Ce que ce cours peut vous apporter</th></tr></thead><tbody><tr><td>Étudiant</td><td>Devoirs, concours, création d&#39;entreprise : réalisez vos projets vous-même, sans dépendre de personne</td></tr><tr><td>Professionnel</td><td>Automatisez les tâches répétitives, améliorez votre efficacité, voire développez un projet parallèle</td></tr><tr><td>Chef de produit / Designer</td><td>Vos idées ne restent plus sur papier : créez rapidement des démos pour votre patron ou vos clients</td></tr><tr><td>Entrepreneur / PME</td><td>Validez vos idées à moindre coût, créez un MVP sans dépenser des milliers en sous-traitance</td></tr><tr><td>Enseignant / Formateur</td><td>Créez des outils pédagogiques, des supports de cours, générez automatiquement des exercices</td></tr><tr><td>Médecin / Avocat / Professionnel</td><td>Automatisez vos processus métier, créez vos propres outils d&#39;efficacité</td></tr><tr><td>Tout le monde</td><td>Utilisez l&#39;IA pour résoudre des problèmes concrets du quotidien ou professionnel, rendez l&#39;impossible possible</td></tr></tbody></table><p>À l&#39;ère de l&#39;IA, la capacité d&#39;exécution et les idées sont toujours plus importantes que la technique.</p><h2 id="parcours-de-croissance-de-«-savoir-utiliser-l-ia-»-a-«-savoir-creer-des-produits-ai-»" tabindex="-1">Parcours de croissance : de « savoir utiliser l&#39;IA » à « savoir créer des produits AI » <a class="header-anchor" href="#parcours-de-croissance-de-«-savoir-utiliser-l-ia-»-a-«-savoir-creer-des-produits-ai-»" aria-label="Permalink to “Parcours de croissance : de « savoir utiliser l&#39;IA » à « savoir créer des produits AI »”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>Débutant</h3><p class="stage-role">Découvrir la programmation AI</p><div class="stage-tags"><span>Jeu du serpent</span><span>Prise en main sans prérequis</span><span>Première expérience Vibe Coding</span><span>Génération en quelques minutes</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>Première étape</h3><p class="stage-role">Chef de produit / Operations</p><div class="stage-tags"><span>IDE AI (Cursor/Claude)</span><span>Décomposition des besoins &amp; Prototype</span><span>Intégration de capacités AI</span><span>Développement complet d&#39;une démo</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>Deuxième étape</h3><p class="stage-role">Développeur junior / Développeur indépendant</p><div class="stage-tags"><span>De Figma au code</span><span>Base de données Supabase</span><span>Intégration de paiement Stripe</span><span>Base de connaissances Dify</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>Troisième étape</h3><p class="stage-role">Développeur senior / Architecte</p><div class="stage-tags"><span>Web/Mini-programmes/Multi-plateforme</span><span>Outils avancés MCP</span><span>RAG &amp; LangGraph</span><span>Mentalité d&#39;ingénieur senior</span></div></div></div><p>À travers ce parcours d&#39;apprentissage complet, vous acquerrez :</p><ul><li><strong>Compétences en développement Vibe Coding :</strong> Maîtrisez la mentalité du Vibe Coding et les outils de codage AI pour multiplier votre efficacité de développement. Au lieu de mémoriser la syntaxe, apprenez à guider l&#39;IA pour qu&#39;elle génère du code de haute qualité.</li><li><strong>Compétences en développement full-stack :</strong> De la conception UI à l&#39;implémentation frontend, de la conception de base de données au développement d&#39;API, du développement local au déploiement cloud, maîtrisez la stack technologique complète des applications Web modernes.</li><li><strong>Intégration de capacités AI :</strong> Apprenez à appeler diverses API AI multimodales, intégrez de manière transparente les capacités AI de texte, image et voix dans vos applications, et construisez des produits intelligents grâce à des technologies comme le RAG.</li><li><strong>Réflexion produit et compétences opérationnelles :</strong> De la recherche utilisateur à la décomposition des besoins, de la conception MVP à l&#39;itération produit, de l&#39;intégration des paiements à la gestion des utilisateurs, formez un cycle complet de développement et d&#39;exploitation de produits.</li></ul><h1 id="que-pourrez-vous-faire-apres-avoir-appris" tabindex="-1">Que pourrez-vous faire après avoir appris ? <a class="header-anchor" href="#que-pourrez-vous-faire-apres-avoir-appris" aria-label="Permalink to “Que pourrez-vous faire après avoir appris ?”">​</a></h1><h2 id="premiere-etape-creer-votre-premier-prototype-de-produit" tabindex="-1">Première étape : Créer votre premier prototype de produit <a class="header-anchor" href="#premiere-etape-creer-votre-premier-prototype-de-produit" aria-label="Permalink to “Première étape : Créer votre premier prototype de produit”">​</a></h2><p>Cette étape est destinée à ceux qui n&#39;ont aucune base en programmation, ou qui n&#39;en ont qu&#39;une petite mais manquent de confiance. Vous n&#39;avez pas besoin d&#39;apprendre d&#39;abord beaucoup de théorie — vous apprenez directement en pratiquant, en utilisant des outils AI pour écrire du code.</p><p><strong>Après avoir appris, vous pourrez :</strong></p><ul><li>Utiliser des outils de programmation AI pour réaliser indépendamment une application web</li><li>Transformer une idée produit en un prototype cliquable et interactif</li><li>Ajouter des fonctionnalités AI à votre prototype (par exemple, génération d&#39;images à partir de texte, conversation intelligente)</li><li>Savoir comment diagnostiquer et résoudre les erreurs</li></ul><p>En bref, vous serez capable de créer quelque chose qui « fonctionne et peut être montré à d&#39;autres ».</p><p>Nous pouvons d&#39;abord découvrir la programmation AI à travers des petits jeux, puis apprendre à utiliser des outils de programmation AI pour vous aider à écrire du code et corriger les erreurs. Ensuite, en commençant par des pages simples, nous réaliserons progressivement des applications multi-pages interactives, puis ajouterons des fonctionnalités AI comme la génération d&#39;images à partir de texte et les conversations intelligentes. Enfin, vous réaliserez indépendamment un projet complet, donnant à vos idées une véritable chance de se concrétiser.</p><h1 id="pourquoi-utiliser-une-approche-par-projets-pour-s-entrainer" tabindex="-1">Pourquoi utiliser une approche par projets pour s&#39;entraîner ? <a class="header-anchor" href="#pourquoi-utiliser-une-approche-par-projets-pour-s-entrainer" aria-label="Permalink to “Pourquoi utiliser une approche par projets pour s&#39;entraîner ?”">​</a></h1><blockquote><p><strong>Les défis du monde réel</strong></p><p>La raison est en fait assez simple : dans l&#39;état actuel de la plupart des étudiants, entrer directement dans le monde professionnel signifierait se faire rudement « corriger » par les projets réels et les patrons / clients. Les scénarios les plus courants dans le monde réel sont plutôt :</p></blockquote><blockquote><p>Votre mentor / patron : Nous devons créer un xxx, l&#39;objectif est d&#39;atteindre l&#39;effet yyy.</p><p>Documentation ? Framework existant ? Spécifications détaillées ? Bien souvent, rien de tout cela n&#39;existe.</p></blockquote><p>De nombreuses tâches dans le travail réel consistent essentiellement à résoudre des problèmes jamais vus auparavant dans un environnement hautement incertain : les besoins sont flous, les périmètres évoluent, personne ne vous donne de réponse standard. Vous devez chercher vous-même des informations, faire des expériences, construire des prototypes, itérer constamment, et finalement proposer une solution « qui fonctionne, qui est utilisable et qui peut être mise en ligne ».</p><p>Ce que ce cours cherche à faire, c&#39;est de vous donner une « simulation de correction du monde réel » dans un environnement relativement sûr :</p><ul><li>Par des projets qui semblent difficiles, vous forcer à pratiquer la décomposition de problèmes, la conception de solutions et la recherche autonome d&#39;informations</li><li>Par des outils et du code qui ne sont pas « simplifiés à l&#39;extrême », vous apprendre à lire, comprendre et modifier une base de code de taille moyenne à grande</li><li>Par un cycle complet de l&#39;idée à la mise en ligne, vous faire vivre le processus complet de création d&#39;un produit de 0 à 1</li></ul><p>À court terme, cet entraînement est effectivement exigeant ; mais à long terme, il augmentera considérablement votre compétitivité dans votre recherche d&#39;emploi et votre évolution professionnelle : vous serez plus capable de supporter la pression, de trouver des percées dans des environnements incertains, et plus capable de transformer l&#39;IA en produits réellement déployés, au lieu de rester au stade des « démos ».</p><h1 id="l-art-de-poser-des-questions-une-competence-essentielle-a-l-ere-de-l-ia" tabindex="-1">L&#39;art de poser des questions : une compétence essentielle à l&#39;ère de l&#39;IA <a class="header-anchor" href="#l-art-de-poser-des-questions-une-competence-essentielle-a-l-ere-de-l-ia" aria-label="Permalink to “L&#39;art de poser des questions : une compétence essentielle à l&#39;ère de l&#39;IA”">​</a></h1><p>À l&#39;ère de l&#39;IA, savoir poser des questions est aussi une « compétence fondamentale ». Pour un même code, une même erreur, <strong>la façon dont vous posez la question détermine presque la qualité de la réponse que l&#39;IA peut donner</strong> : une réponse générique ou une correction étape par étape applicable.</p><p><strong>Prenez une bonne habitude :</strong> intégrez « poser des questions à l&#39;IA » dans votre flux de développement quotidien : dès que vous ne comprenez pas quelque chose ou que vous êtes bloqué, posez la question immédiatement.</p><h2 id="pourquoi-est-ce-une-competence-essentielle" tabindex="-1">Pourquoi est-ce une compétence essentielle ? <a class="header-anchor" href="#pourquoi-est-ce-une-competence-essentielle" aria-label="Permalink to “Pourquoi est-ce une compétence essentielle ?”">​</a></h2><ul><li><strong>Rarement il existe une documentation complète dans la réalité</strong> : la plupart du temps, vous êtes confronté à des besoins imprécis, du code à moitié fini, des messages d&#39;erreur épars</li><li><strong>L&#39;IA est votre mentor et collègue de toujours</strong> : une personne qui sait poser des questions peut en faire un « pair programming de haute qualité »</li><li><strong>La limite de vos capacités est déterminée par votre communication</strong> : plus vous fournissez d&#39;informations clés et plus vous contraignez le format de sortie, plus la réponse sera utilisable</li></ul><p><strong>Malentendu courant :</strong> poser simplement « pourquoi ça plante ? » ne donnera souvent que des suppositions. Complétez le contexte pour obtenir des solutions actionnables.</p><h2 id="comment-«-nourrir-»-l-ia-en-informations-capture-d-ecran-vs-copier-coller" tabindex="-1">Comment « nourrir » l&#39;IA en informations : capture d&#39;écran vs copier-coller <a class="header-anchor" href="#comment-«-nourrir-»-l-ia-en-informations-capture-d-ecran-vs-copier-coller" aria-label="Permalink to “Comment « nourrir » l&#39;IA en informations : capture d&#39;écran vs copier-coller”">​</a></h2><p>Les deux méthodes fonctionnent, mais pour des usages différents :</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Scénarios appropriés</th><th>Points clés</th></tr></thead><tbody><tr><td><strong>Copier-coller</strong></td><td>Piles d&#39;erreurs, logs, code, configuration, réponses d&#39;API</td><td>Copiez le plus complètement possible, ne vous contentez pas d&#39;une seule ligne clé</td></tr><tr><td><strong>Capture d&#39;écran</strong></td><td>Problèmes de mise en page UI, anomalies d&#39;interaction, interface d&#39;outil où vous ne trouvez pas un bouton</td><td>Capture d&#39;écran complète + annotation des zones importantes, idéalement avec une brève description textuelle</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ Prérequis important</p><p><strong>Tous les modèles AI ne prennent pas en charge l&#39;entrée d&#39;images.</strong> La communication par capture d&#39;écran nécessite que l&#39;IA possède des capacités multimodales (c&#39;est-à-dire la capacité de comprendre et d&#39;analyser des images). Les AI prenant actuellement en charge l&#39;entrée d&#39;images incluent : Claude (Anthropic), GPT-4V/GPT-4o (OpenAI), Gemini (Google), ainsi que certains modèles chinois comme Qwen, ERNIE Bot, etc.</p><p><strong>Si l&#39;IA que vous utilisez ne prend pas en charge l&#39;entrée d&#39;images</strong>, les captures d&#39;écran ne pourront pas être reconnues. Dans ce cas, utilisez plutôt la méthode du copier-coller de texte.</p></div><h2 id="techniques-de-prompt-pour-que-l-ia-«-explique-bien-»" tabindex="-1">Techniques de prompt pour que l&#39;IA « explique bien » <a class="header-anchor" href="#techniques-de-prompt-pour-que-l-ia-«-explique-bien-»" aria-label="Permalink to “Techniques de prompt pour que l&#39;IA « explique bien »”">​</a></h2><p>Si vous ne voulez pas seulement la réponse, mais « comprendre » la réponse, utiliser des instructions similaires à celles ci-dessous améliorera significativement la qualité des explications :</p><blockquote><p><strong>Exemple de question d&#39;apprentissage</strong></p><ul><li>« Explique-moi d&#39;abord ce concept en 5 phrases, puis pose-moi quelques questions pour vérifier que j&#39;ai bien compris. »</li><li>« Explique-moi en détail ce message d&#39;erreur, je ne comprends pas pourquoi cela plante. »</li></ul></blockquote><h1 id="j-ai-persevere-longtemps-mais-je-n-y-arrive-toujours-pas-je-veux-abandonner" tabindex="-1">J&#39;ai persévéré longtemps mais je n&#39;y arrive toujours pas, je veux abandonner <a class="header-anchor" href="#j-ai-persevere-longtemps-mais-je-n-y-arrive-toujours-pas-je-veux-abandonner" aria-label="Permalink to “J&#39;ai persévéré longtemps mais je n&#39;y arrive toujours pas, je veux abandonner”">​</a></h1><p>C&#39;est peut-être votre méthode de persévérance qui n&#39;est pas la bonne. Ne vous débattez pas seul dans le noir — venez discuter avec les auteurs et les assistants : exposez honnêtement les méthodes que vous avez déjà essayées, les blocages spécifiques que vous rencontrez, et votre état psychologique actuel. Très souvent, un léger ajustement de direction ou l&#39;ajout d&#39;une connaissance clé vous permettra de continuer à avancer.</p><h1 id="je-trouve-que-certains-aspects-du-tutoriel-ne-sont-pas-bien-concus" tabindex="-1">Je trouve que certains aspects du tutoriel ne sont pas bien conçus <a class="header-anchor" href="#je-trouve-que-certains-aspects-du-tutoriel-ne-sont-pas-bien-concus" aria-label="Permalink to “Je trouve que certains aspects du tutoriel ne sont pas bien conçus”">​</a></h1><p>N&#39;hésitez pas à contacter les auteurs, à soumettre une issue, ou à faire part de vos retours dans le groupe ou en cours. Nous espérons vraiment travailler avec vous pour perfectionner ce tutoriel : ce qui n&#39;est pas clair, ce qui donne une mauvaise expérience, ce qui vous fait perdre du temps inutilement — tout cela peut être signalé franchement. Plus les retours sont authentiques et spécifiques, plus ils aideront les futurs apprenants à éviter les pièges.</p><h1 id="references" tabindex="-1">Références <a class="header-anchor" href="#references" aria-label="Permalink to “Références”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">Université de Nanking, Département d&#39;informatique, Fondamentaux des systèmes informatiques, Travaux pratiques</a></li></ul>',50)),u(s,{title:"Que pouvez-vous apprendre ensuite",description:"Continuez à progresser selon le parcours « de savoir utiliser l'IA à savoir créer des produits ».",items:l(r)},null,8,["items"])])}}});export{g as __pageData,h as default};
